def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)
    target_sum = n * (n * n + 1) // 2

    # Check if all rows have the correct sum
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check if all columns have the correct sum
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False

    # Check if all diagonals have the correct sum
    sum_main = sum(matrix[i][i] for i in range(n))
    sum_anti = sum(matrix[i][n - 1 - i] for i in range(n))
    if sum_main != target_sum or sum_anti != target_sum:
        return False

    # Check if all numbers from 1 to n^2 are present exactly once
    seen = set()
    for row in matrix:
        for num in row:
            if not (1 <= num <= n * n):
                return False
            seen.add(num)

    if len(seen) != n * n:
        return False

    return True
