def ncr_modp(n, r, p):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1 % p
    # Compute nCr % p using Lucas' theorem for prime p
    res = 1
    n_copy, r_copy = n, r
    while n_copy > 0 or r_copy > 0:
        ni = n_copy % p
        ri = r_copy % p
        if ni >= ri:
            res = (res * ni) % p
        if ni - ri >= 0:
            res = (res * (ni - ri)) % p
        n_copy //= p
        r_copy //= p
    return res
```

