def pancake_sort(arr):
    def flip(arr, i):
        """Flip the first i elements of arr."""
        arr[:i] = arr[:i][::-1]

    def sort(arr):
        """Sort the array using pancake sort."""
        n = len(arr)
        for size in range(n, 1, -1):
            # Find the index of the maximum element in the current unsorted portion
            max_idx = max(range(size), key=lambda x: arr[x])

            # Move the maximum element to the top
            if max_idx != 0:
                flip(arr, max_idx + 1)

            # Move the maximum element to the current end of the unsorted portion
            if max_idx != size - 1:
                flip(arr, size)

        return arr

    return sort(arr)
```

