def search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return arr[mid]
        # Since the array is sorted and pairs are adjacent,
        # if mid is even, the next element should be the same if it's a pair.
        # If arr[mid] < target, the target must be on the right.
        # If arr[mid] > target, the target must be on the left.
        if mid % 2 == 0:
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        else:
            # If mid is odd, it's the second element of a pair.
            # If arr[mid] < target, the target is on the right.
            # If arr[mid] > target, the target is on the left.
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
    return -1
```

