def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)
    target_sum = n * (n * n + 1) // 2

    # Check all rows
    for i in range(n):
        row_sum = sum(matrix[i])
        if row_sum != target_sum:
            return False

    # Check all columns
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != target_sum:
            return False

    # Check both diagonals
    diag1 = sum(matrix[i][i] for i in range(n))
    diag2 = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag1 != target_sum or diag2 != target_sum:
        return False

    # Check all numbers from 1 to n^2 are present exactly once
    seen = set()
    for i in range(n):
        for j in range(n):
            val = matrix[i][j]
            if val < 1 or val > n * n or val in seen:
                return False
            seen.add(val)

    return True
